function readTeacherAvailabilityMap_() {
  var sheet = getOrCreateTeacherAvailabilitySheet_();
  var lastRow = sheet.getLastRow();
  var map = {};
  if (lastRow < 2) return map;
  var values = sheet.getRange(2, 1, lastRow - 1, 11).getValues();
  values.forEach(function (row, i) {
    var weekId = row[0], courseId = String(row[3]);
    if (!weekId || !courseId) return;
    map[weekId + '|' + courseId] = {
      rowNum: i + 2,
      weekId: weekId,
      teacherEmail: row[1],
      teacherName: row[2],
      courseId: courseId,
      courseName: row[4],
      section: row[5],
      status: row[6] || AVAILABILITY_STATUS.PENDING,
      alternative: row[7] || '',
      updatedAt: row[8] || '',
      updatedByEmail: row[9] || '',
      updatedByName: row[10] || ''
    };
  });
  return map;
}

